using namespace dve;using namespace dve::editor;
namespace {
void check(bool v,const std::string& m){if(!v)throw std::runtime_error(m);}
template<class P> void until(P p){auto end=std::chrono::steady_clock::now()+std::chrono::seconds(20);while(!p()){check(std::chrono::steady_clock::now()<end,"Network worker timeout");std::this_thread::yield();}}
void add(EditorDocument& d,EditorObjectId id,double x,double z,unsigned samples=3,bool adaptive=false){auto s=make_nurbs_patch(2);for(auto& p:s.controls){p.x+=x;p.z=z-p.z;p.y=0;}s.samplesPerSpan=samples;s.adaptiveDisplay=adaptive;s.chordTolerance=.03;s.normalAngle=.2;auto o=make_editor_nurbs(id,s);check(bool(o),"Network patch fixture");d.add_object(std::move(*o));}
void link(EditorDocument& d,EditorObjectId a,EditorObjectId b,NurbsBoundary ea,NurbsBoundary eb,bool c1){auto r=link_nurbs_seam_command(a,b,{ea,eb,false,c1})->execute(d);check(r.success,"Link "+std::to_string(a)+"->"+std::to_string(b)+": "+r.message);}
auto positions(const EditorObject& o,NurbsBoundary edge){auto s=editor_nurbs_source(o);bool v=edge==NurbsBoundary::VMin||edge==NurbsBoundary::VMax,minimum=edge==NurbsBoundary::UMin||edge==NurbsBoundary::VMin;float t=float((v?s->textureV:s->textureU)[minimum?0:1]);std::set<std::tuple<float,float,float>> result;for(const auto& p:o.polygon->vertices)if((v?p.texcoord.y:p.texcoord.x)==t)result.emplace(p.position.x,p.position.y,p.position.z);return result;}
void coherent(const EditorDocument& d){std::string error;check(d.validate(&error),error);for(const auto& [id,o]:d.objects())if(has_nurbs_seam(o)){auto seams=editor_nurbs_seams(o,&error);check(bool(seams),error);for(const auto& seam:*seams)if(id==seam.reference)check(positions(o,seam.options.referenceBoundary)==positions(*d.find_object(seam.moving),seam.options.movingBoundary),"Every incident seam shares bit-identical positions");}}
std::vector<std::string> state(const EditorDocument& d){std::vector<std::string> out;for(const auto& [id,o]:d.objects()){auto* c=find_component_by_type(o.components,kNurbsComponent);out.push_back(std::get<std::string>(c->properties.at("source")));auto it=c->properties.find("seam");out.push_back(it==c->properties.end()?"":std::get<std::string>(it->second));out.push_back(std::to_string(polygon_asset_content_hash(*o.polygon)));}return out;}
void square(EditorDocument& d,bool c1,bool adaptive,bool alternate=false,bool rational=false){add(d,1,0,0,3,adaptive);add(d,2,2,0,5,!adaptive);add(d,3,0,2,4,adaptive);add(d,4,2,2,6,!adaptive);
    if(rational){auto source=*editor_nurbs_source(*d.find_object(1));source.controls[10].weight=.98;check(replace_editor_nurbs_source(*d.find_object(1),source),"Rational root fixture");}
    if(!alternate){link(d,1,2,NurbsBoundary::UMax,NurbsBoundary::UMin,c1);link(d,1,3,NurbsBoundary::VMax,NurbsBoundary::VMin,c1);link(d,2,4,NurbsBoundary::VMax,NurbsBoundary::VMin,c1);link(d,3,4,NurbsBoundary::UMax,NurbsBoundary::UMin,c1);}
    else {link(d,1,3,NurbsBoundary::VMax,NurbsBoundary::VMin,c1);link(d,1,2,NurbsBoundary::UMax,NurbsBoundary::UMin,c1);link(d,3,4,NurbsBoundary::UMax,NurbsBoundary::UMin,c1);link(d,2,4,NurbsBoundary::VMax,NurbsBoundary::VMin,c1);}
    coherent(d);
}
void junctions_and_history(){
    for(bool c1:{false,true})for(bool adaptive:{false,true})for(bool rational:{false,true}){
        EditorDocument d("Four patch junction"),other("Different link order");square(d,c1,adaptive,false,rational);square(other,c1,adaptive,true,rational);check(state(d)==state(other),"Network output independent of link insertion order");
        for(const auto& [id,o]:d.objects())check(editor_nurbs_seams(o)->size()==2,"Two seams per square patch");
        auto stable=state(d);for(unsigned repeat=0;repeat<3;++repeat){auto refresh=refresh_nurbs_seam_command(4)->execute(d);check(refresh.success,refresh.message);coherent(d);}check(state(d)==stable,"Repeated network refresh is stable");
        auto before=state(d);auto source=*editor_nurbs_source(*d.find_object(1)),after=source;after.controls[15].y+=.08;EditorCommandStack history;auto r=history.execute(d,std::make_unique<EditNurbsCommand>(1,source,after));check(r.success,r.message);coherent(d);check(editor_nurbs_source(*d.find_object(4))!=editor_nurbs_source(*other.find_object(4)),"Root corner edit reaches converging downstream patch");
        auto edited=state(d);check(history.undo(d).success&&state(d)==before,"One undo restores every network source/cache/record");check(history.redo(d).success&&state(d)==edited,"One redo restores complete network");coherent(d);
        auto leafSource=*editor_nurbs_source(*d.find_object(4)),bad=leafSource;bad.controls[0].y+=.1;auto count=history.size();r=history.execute(d,std::make_unique<EditNurbsCommand>(4,leafSource,bad));check(!r.success&&state(d)==edited&&history.size()==count,"Any incoming driven row protects a converging patch atomically");
        auto preset=*editor_nurbs_source(*d.find_object(2)),fine=preset;fine.adaptiveDisplay=!preset.adaptiveDisplay;r=history.execute(d,std::make_unique<EditNurbsCommand>(2,preset,fine));check(r.success,r.message);coherent(d);
        auto unlink=unlink_nurbs_seam_command(1);auto linked=state(d);r=unlink->execute(d);check(r.success,r.message);check(!has_nurbs_seam(*d.find_object(1))&&nurbs_seam_network_ids(d,2).size()==3,"Unlink detaches selected patch and retains remaining seams");coherent(d);check(unlink->undo(d).success&&state(d)==linked,"Unlink undo restores all incident relationships");coherent(d);
        RemoveObjectsCommand partial({1,2,3});check(!partial.execute(d).success,"Partial network deletion refuses");RemoveObjectsCommand entire({1,2,3,4});check(entire.execute(d).success&&d.objects().empty()&&entire.undo(d).success,"Whole network delete/undo");coherent(d);
        const auto dir=std::filesystem::temp_directory_path()/"dve_nurbs_network_test";std::filesystem::remove_all(dir);std::filesystem::create_directories(dir);auto saved=d.save_transactional(dir/"network.dvescene");check(saved.success,saved.error);std::string error;auto loaded=EditorDocument::load(dir/"network.dvescene",&error);check(bool(loaded),error);coherent(*loaded);check(state(d)==state(*loaded),"Network records round-trip through scene storage");std::filesystem::remove_all(dir);
    }
    EditorDocument star("Four incident boundaries");add(star,1,0,0);add(star,2,2,0);add(star,3,-2,0);add(star,4,0,2);add(star,5,0,-2);
    link(star,1,2,NurbsBoundary::UMax,NurbsBoundary::UMin,true);link(star,1,3,NurbsBoundary::UMin,NurbsBoundary::UMax,true);link(star,1,4,NurbsBoundary::VMax,NurbsBoundary::VMin,true);link(star,1,5,NurbsBoundary::VMin,NurbsBoundary::VMax,true);check(editor_nurbs_seams(*star.find_object(1))->size()==4,"All four boundaries supported");coherent(star);
}
void arbitrary_network_axes(){
    const std::array<NurbsBoundary,4> edges{NurbsBoundary::UMin,NurbsBoundary::UMax,NurbsBoundary::VMin,NurbsBoundary::VMax};
    auto endpoint=[](const NurbsSource& s,NurbsBoundary e,bool high){const bool v=e==NurbsBoundary::VMin||e==NurbsBoundary::VMax,minimum=e==NurbsBoundary::UMin||e==NurbsBoundary::VMin;return evaluate_nurbs(s,v?(high?s.u.knots.back():s.u.knots.front()):(minimum?s.u.knots.front():s.u.knots.back()),v?(minimum?s.v.knots.front():s.v.knots.back()):(high?s.v.knots.back():s.v.knots.front()))->position;};
    auto same=[](const auto& a,const auto& b){for(unsigned k=0;k<3;++k)if(std::abs(a[k]-b[k])>1e-12)return false;return true;};
    for(unsigned variant=0;variant<8;++variant){
        EditorDocument d("Reparameterized junction");add(d,1,0,0,3);add(d,2,2,0,5,true);add(d,3,0,2,4);add(d,4,2,2,6,true);
        for(unsigned id=1;id<=4;++id){auto source=*editor_nurbs_source(*d.find_object(id));unsigned bits=(variant+id*3)%8;if(bits&1)source=*transpose_nurbs(source);if(bits&2)source=*reverse_nurbs_axis(source,false);if(bits&4)source=*reverse_nurbs_axis(source,true);check(replace_editor_nurbs_source(*d.find_object(id),source),"Reparameterized fixture");}
        auto connect=[&](EditorObjectId a,EditorObjectId b){auto sa=*editor_nurbs_source(*d.find_object(a)),sb=*editor_nurbs_source(*d.find_object(b));for(auto ea:edges)for(auto eb:edges)for(bool reverse:{false,true})if(same(endpoint(sa,ea,false),endpoint(sb,eb,reverse))&&same(endpoint(sa,ea,true),endpoint(sb,eb,!reverse))){auto r=link_nurbs_seam_command(a,b,{ea,eb,reverse,true})->execute(d);check(r.success,r.message);return;}throw std::runtime_error("Expected shared geometric edge");};
        connect(1,2);connect(1,3);connect(2,4);connect(3,4);coherent(d);auto source=*editor_nurbs_source(*d.find_object(1)),after=source;for(auto& p:after.controls)p.y+=.03;auto r=edit_nurbs_seam_command(1,source,after)->execute(d);check(r.success,r.message);coherent(d);
    }
}
void refusals_and_corruption(){
    EditorDocument d("Directed cycle");for(unsigned i=1;i<=3;++i)add(d,i,2*(i-1),0);link(d,1,2,NurbsBoundary::UMax,NurbsBoundary::UMin,true);link(d,2,3,NurbsBoundary::UMax,NurbsBoundary::UMin,true);auto before=state(d);auto r=link_nurbs_seam_command(3,1,{NurbsBoundary::UMax,NurbsBoundary::UMin})->execute(d);check(!r.success&&r.message.find("Cyclic")!=std::string::npos&&state(d)==before,"Directed cycles refuse atomically");
    add(d,4,0,2);before=state(d);r=link_nurbs_seam_command(1,4,{})->execute(d);check(!r.success&&r.message.find("boundary")!=std::string::npos&&state(d)==before,"Occupied boundary refuses");
    d.find_object(3)->flags.locked=true;auto source=*editor_nurbs_source(*d.find_object(1)),after=source;after.controls[7].y=.1;r=edit_nurbs_seam_command(1,source,after)->execute(d);check(!r.success&&state(d)==before,"Locked distant patch prevents entire edit");d.find_object(3)->flags.locked=false;
    EditorDocument conflict("Incompatible junction");add(conflict,1,0,0);add(conflict,2,3,3);add(conflict,3,2,0);link(conflict,1,3,NurbsBoundary::UMax,NurbsBoundary::UMin,false);before=state(conflict);r=link_nurbs_seam_command(2,3,{NurbsBoundary::VMax,NurbsBoundary::VMin})->execute(conflict);check(!r.success&&state(conflict)==before,"Incompatible incoming corner constraints refuse without breaking existing seam");coherent(conflict);
    EditorDocument squareDoc("Malformed network");square(squareDoc,true,false);auto* object=squareDoc.find_object(1);auto* component=find_component_by_type(std::span<Component>(object->components),kNurbsComponent);auto original=std::get<std::string>(component->properties.at("seam"));component->properties["seam"]=std::string("DVE_NURBS_SEAMS 2 5");check(!squareDoc.validate(),"More than four incident records rejected");component->properties["seam"]=original;coherent(squareDoc);
    auto* remote=squareDoc.find_object(4);auto* rc=find_component_by_type(std::span<Component>(remote->components),kNurbsComponent);auto record=std::get<std::string>(rc->properties.at("seam"));rc->properties.erase("seam");check(!squareDoc.validate(),"Missing remote reciprocity rejected");rc->properties["seam"]=record;coherent(squareDoc);
    EditorDocument budget("Network node budget");for(unsigned i=1;i<=17;++i)add(budget,i,2*(i-1),0,1);for(unsigned i=1;i<16;++i)link(budget,i,i+1,NurbsBoundary::UMax,NurbsBoundary::UMin,false);before=state(budget);r=link_nurbs_seam_command(16,17,{})->execute(budget);check(!r.success&&state(budget)==before,"17th patch exceeds bounded network budget atomically");
}
void native_link_menus(){
    auto owner=std::make_unique<NativeEditorController>(EditorWorkspace(EditorDocument("Network menus")));auto& c=*owner;c.resize(1600,1000);auto& d=c.workspace().document();add(d,1,0,0);add(d,2,2,0);add(d,3,0,2);
    c.workspace().select_object(2);c.workspace().add_to_selection(1);check(c.dispatch_action("nurbs.seam_link_c1"),c.status().text);
    c.workspace().select_object(3);c.workspace().add_to_selection(1);check(c.dispatch_action("nurbs.attach_reference_vmax")&&c.dispatch_action("nurbs.attach_moving_vmin"),"Choose a second free boundary");c.refresh_menu_state();
    check(std::as_const(c.workspace().menus()).find("nurbs.seam_link_c1")->enabled,"Already-linked patch offers another free boundary");check(c.dispatch_action("nurbs.seam_link_c1"),c.status().text);check(editor_nurbs_seams(*d.find_object(1))->size()==2,"Native second incident seam");coherent(d);
    c.workspace().select_object(1);d.find_object(2)->flags.locked=true;c.refresh_menu_state();check(!std::as_const(c.workspace().menus()).find("nurbs.seam_refresh")->enabled&&!c.dispatch_action("nurbs.seam_unlink"),"Distant lock disables network refresh/unlink");d.find_object(2)->flags.locked=false;
    check(c.dispatch_action("nurbs.seam_unlink")&&!has_nurbs_seam(*d.find_object(1))&&!has_nurbs_seam(*d.find_object(2))&&!has_nurbs_seam(*d.find_object(3)),"Native unlink detaches all selected incident seams");check(c.dispatch_action("edit.undo"),"Native unlink undo");coherent(d);
}
void worker_and_native(){
    auto owner=std::make_unique<NativeEditorController>(EditorWorkspace(EditorDocument("Network native")));auto& c=*owner;c.resize(1600,1000);auto& d=c.workspace().document();square(d,true,true);auto initial=state(d);
    auto snapshot=capture_nurbs_seam_drag(d,1);check(snapshot&&snapshot->objects().size()==4,"Worker captures entire network");auto source=*editor_nurbs_source(*d.find_object(1)),after=source;NurbsTessellationQueue queue;for(unsigned i=0;i<12;++i){after.controls[15].y=.002*i;queue.submit(snapshot,1,after);}after.controls[15].y=.05;auto generation=queue.submit(snapshot,1,after);std::optional<NurbsTessellationQueue::Result> result;until([&]{result=queue.poll();return result.has_value();});check(result->generation==generation&&result->seamCommand,result->error);check(result->seamCommand->execute(d).success,"Prepared network execute");coherent(d);check(result->seamCommand->undo(d).success&&state(d)==initial,"Prepared network undo");
    std::stop_source cancelled;cancelled.request_stop();std::string error;check(!PreparedNurbsSeamEdit::prepare(snapshot,1,after,&error,cancelled.get_token()),"Pre-cancelled network prepares no partial command");
    auto heavy=source;heavy.adaptiveDisplay=true;heavy.chordTolerance=1e-9;heavy.normalAngle=1e-5;heavy.controls[15].y=.5;
    {auto begin=std::chrono::steady_clock::now();{NurbsTessellationQueue dying;dying.submit(snapshot,1,heavy);std::this_thread::sleep_for(std::chrono::milliseconds(20));dying.cancel();check(!dying.poll(),"Cancelled network delivers no result");}check(std::chrono::steady_clock::now()-begin<std::chrono::seconds(5),"Network cancellation and worker shutdown return promptly");}
    c.workspace().select_object(1);check(c.dispatch_action("nurbs.edit")&&c.select_nurbs_controls({15},SelectionOperation::Replace),"Native root corner control");auto history=c.workspace().commands().size();
    auto start=[&]{c.set_active_tool(EditorToolId::Translate);auto axis=c.gizmo_axes()[1];c.pointer_down(PointerButton::Primary,int(axis.end.x),int(axis.end.y),0);check(c.gizmo_dragging(),c.status().text);for(auto key:{"0",".","0","5"})c.key_down(key,false,false,false);};auto preview=[&]{until([&]{c.update(0);return editor_nurbs_source(*d.find_object(1))!=source;});coherent(d);};
    start();preview();c.key_down("escape",false,false,false);check(state(d)==initial&&c.workspace().commands().size()==history,"Escape restores all network previews without history");
    start();c.key_down("enter",false,false,false);until([&]{c.update(0);return !c.gizmo_dragging();});check(c.workspace().commands().size()==history+1,"Network drag is one command");coherent(d);check(c.dispatch_action("edit.undo")&&state(d)==initial,"Native network undo restores all objects");check(c.dispatch_action("edit.redo"),"Native network redo");coherent(d);check(c.dispatch_action("edit.undo"),"Restore baseline");
    start();preview();d.find_object(4)->flags.locked=true;c.update(0);check(!c.gizmo_dragging()&&state(d)==initial,"Distant lock restores complete network preview");d.find_object(4)->flags.locked=false;
    start();preview();d.find_object(4)->polygon->materials[0].name="Remote artist material";d.find_object(4)->polygon->contentHash=polygon_asset_content_hash(*d.find_object(4)->polygon);c.key_down("escape",false,false,false);check(d.find_object(4)->polygon->materials[0].name=="Remote artist material"&&editor_nurbs_source(*d.find_object(1))==source,"Cancellation preserves distant material edits");coherent(d);
    start();auto remoteSource=*editor_nurbs_source(*d.find_object(4)),external=remoteSource;external.controls[5].y+=.02;find_component_by_type(std::span<Component>(d.find_object(4)->components),kNurbsComponent)->properties["source"]=encode_nurbs(external);c.update(0);check(!c.gizmo_dragging()&&editor_nurbs_source(*d.find_object(4))==external&&editor_nurbs_source(*d.find_object(1))==source,"External distant source wins over pending work");find_component_by_type(std::span<Component>(d.find_object(4)->components),kNurbsComponent)->properties["source"]=encode_nurbs(remoteSource);coherent(d);
    start();auto* remote=d.find_object(4);remote->polygon->vertices[0].position.y+=.02F;auto hash=polygon_asset_content_hash(*remote->polygon);c.update(0);check(!c.gizmo_dragging()&&polygon_asset_content_hash(*remote->polygon)==hash&&editor_nurbs_source(*d.find_object(1))==source,"External distant cache wins over pending work");
    // Restore the remote cache, then delete a member mid-preview: survivors are restored and detached, never left dangling.
    {auto restored=clone_editor_object(*snapshot->find(4));d.remove_object(4);d.add_object(std::move(restored));}coherent(d);
    std::vector<NurbsSource> sources;for(EditorObjectId id:{1,2,3})sources.push_back(*editor_nurbs_source(*d.find_object(id)));
    const auto historyBefore=c.workspace().commands().size();start();preview();check(d.remove_object(4),"Remove remote patch fixture");c.update(0);std::string invalid;
    check(!c.gizmo_dragging()&&editor_nurbs_source(*d.find_object(1))==sources[0]&&editor_nurbs_source(*d.find_object(2))==sources[1]&&editor_nurbs_source(*d.find_object(3))==sources[2],"Remote deletion restores every surviving source");
    check(d.validate(&invalid)&&!has_nurbs_seam(*d.find_object(1))&&!has_nurbs_seam(*d.find_object(2))&&!has_nurbs_seam(*d.find_object(3))&&c.workspace().commands().size()==historyBefore,"Remote deletion leaves no dangling seam records: "+invalid);
    for(EditorObjectId id:{1,2,3})check(validate_editor_nurbs(*d.find_object(id)),"Survivor display matches its standalone source");
}
}
int main(){try{junctions_and_history();arbitrary_network_axes();refusals_and_corruption();native_link_menus();worker_and_native();std::cout<<"NURBS network tests passed\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
